import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import '../theme/app_theme.dart'; import 'flow_widgets.dart';
class WorkerOnboardingScreen extends StatefulWidget { const WorkerOnboardingScreen({super.key}); @override State<WorkerOnboardingScreen> createState()=>_WorkerOnboardingScreenState(); }
class _WorkerOnboardingScreenState extends State<WorkerOnboardingScreen>{final picked=<String>{}; final skills=['Plumbing','Electrical','Painting','Carpentry','Cleaning','Appliance repair']; @override Widget build(BuildContext c)=>FlowScaffold(title:'Choose skills',child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[flowTitle('What are you skilled at?','Choose one or more services you would like to offer.'),Expanded(child:GridView.count(crossAxisCount:2,childAspectRatio:1.45,crossAxisSpacing:12,mainAxisSpacing:12,children:skills.map((s){final on=picked.contains(s);return AppCard(onTap:()=>setState(()=>on?picked.remove(s):picked.add(s)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.handyman_rounded,color:on?AppTheme.primaryEmerald:AppTheme.textSecondary),const SizedBox(height:8),Text(s,textAlign:TextAlign.center)]));}).toList())),primaryAction('Continue',()=>c.go('/worker-details'))])); }
